contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount) public {
        uint256 balanceBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool burnReverted;
        bool burnReturned;
        bool success = c.burn(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            burnReturned = false;
            burnReverted = true;
        } else {
            burnReturned = success;
            burnReverted = false;
        }

        uint256 balanceAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;

        assert(
            burnReverted
                ? (balanceBefore < amount)
                : (balanceBefore >= amount && burnReturned && balanceAfter == balanceBefore - amount && supplyAfter == supplyBefore - amount)
        );
    }
}

